&lt;style&gt;span.Cat&#233;gorie { display:none; }&lt;/style&gt;&lt;div class=&quot;presentation navmenu&quot;&gt;
&lt;h2 class=&quot;separator&quot;&gt;Acc&#232;s rapide aux sections sur l&#39;&#233;quipement&lt;a class=&quot;headeranchor&quot; id=&quot;Acc&#232;s_rapide_aux_sections_sur_l&#233;quipement_0&quot; href=&quot;#Acc&#232;s_rapide_aux_sections_sur_l&#233;quipement_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&lt;table&gt;&lt;tr style=&quot;vertical-align: top; text-align: left&quot;&gt;&lt;td&gt;
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tableau-R&#233;capitulatif-Des-Armes.html&quot; title=&quot;Tableau r&#233;capitulatif des armes&quot;&gt;Les armes&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Armes.html&quot; title=&quot;Descriptions individuelles des armes&quot;&gt;descriptions&lt;/a&gt;)&lt;/li&gt;
	&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armes.html&quot; title=&quot;Caract&#233;ristiques des armes&quot;&gt;caract&#233;ristiques&lt;/a&gt;&lt;/li&gt;&lt;/ul&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tableau-R&#233;capitulatif-Des-Armes-&#192;-Feu.html&quot; title=&quot;Tableau r&#233;capitulatif des armes &#224; feu&quot;&gt;Les armes &#224; feu&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Armes-&#192;-Feu.html&quot; title=&quot;Descriptions individuelles des armes &#224; feu&quot;&gt;descriptions&lt;/a&gt;)&lt;/li&gt;
	&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Armes-&#192;-Feu.html&quot; title=&quot;Caract&#233;ristiques des armes &#224; feu&quot;&gt;caract&#233;ristiques&lt;/a&gt;&lt;/li&gt;&lt;/ul&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tableau-R&#233;capitulatif-Des-Armures.html&quot; title=&quot;Tableau r&#233;capitulatif des armures&quot;&gt;Les armures&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Armures.html&quot; title=&quot;Descriptions individuelles des armures&quot;&gt;descriptions&lt;/a&gt;)&lt;/li&gt;
	&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armures.html&quot; title=&quot;Caract&#233;ristiques des armures&quot;&gt;caract&#233;ristiques&lt;/a&gt;&lt;/li&gt;&lt;/ul&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mat&#233;riaux-Sp&#233;ciaux.html&quot; title=&quot;Les mat&#233;riaux sp&#233;ciaux&quot;&gt;Les mat&#233;riaux sp&#233;ciaux&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/td&gt;&lt;td&gt;
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Animaux,%20montures%20et%20leur%20%C3%A9quipement.ashx#&quot; title=&quot;Animaux, montures et leur &#233;quipement&quot;&gt;Animaux, montures et leur &#233;quipement&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chroniques-Des-&#201;claireurs.html&quot; title=&quot;Chroniques des Explorateurs&quot;&gt;Chroniques des Explorateurs&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;%C3%89quipement%20daventurier.ashx#&quot; title=&quot;&#201;quipement d&amp;#39;aventurier&quot;&gt;&#201;quipement d&#39;aventurier&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Focalisateurs%20de%20canalisation.ashx#&quot; title=&quot;Focalisateurs de canalisation&quot;&gt;Focalisateurs de canalisation&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;H%C3%A9bergement%20et%20services.ashx#&quot; title=&quot;H&#233;bergement et services&quot;&gt;H&#233;bergement et services&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Jeux.ashx#&quot; title=&quot;Jeux&quot;&gt;Jeux&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;March%C3%A9%20noir.ashx#&quot; title=&quot;March&#233; noir&quot;&gt;March&#233; noir&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/td&gt;&lt;td&gt;
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Moyens%20de%20transport.ashx#&quot; title=&quot;Moyens de transport&quot;&gt;Moyens de transport&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Nourriture%20et%20Boissons.ashx#&quot; title=&quot;Nourriture et Boissons&quot;&gt;Nourriture et Boissons&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Outils%20de%20comp%C3%A9tences.ashx#&quot; title=&quot;Outils de comp&#233;tences&quot;&gt;Outils de comp&#233;tences&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Trousses%20d%C3%A9quipement.ashx#&quot; title=&quot;Trousses d&amp;#39;&#233;quipement&quot;&gt;Trousses d&#39;&#233;quipement&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;V%C3%AAtements.ashx#&quot; title=&quot;V&#234;tements&quot;&gt;V&#234;tements&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Poisons.ashx#&quot; title=&quot;Les poisons  &quot;&gt;Poisons&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/td&gt;&lt;td&gt;
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Armes%20alchimiques.ashx#&quot; title=&quot;Armes alchimiques&quot;&gt;Armes alchimiques&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Outils%20alchimiques.ashx#&quot; title=&quot;Outils alchimiques&quot;&gt;Outils alchimiques&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Rem%C3%A8des%20alchimiques.ashx#&quot; title=&quot;Rem&#232;des alchimiques&quot;&gt;Rem&#232;des alchimiques&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Argent-Et-Richesse.html&quot; title=&quot;Argent et richesse&quot;&gt;L&#39;argent et la richesse&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Marchandises.html&quot; title=&quot;Marchandises&quot;&gt;Les marchandises&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Poids-Transportable.html&quot; title=&quot;Poids transportable&quot;&gt;Le poids transportable&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#233;actifs-Alchimiques.html&quot; title=&quot;R&#233;actifs alchimiques&quot;&gt;Les r&#233;actifs alchimiques&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/div&gt;&lt;i&gt;Les armes d&#233;crites ci-dessous sont celles pr&#233;sent&#233;es dans le &lt;a class=&quot;pagelink&quot; href=&quot;Tableau-R&#233;capitulatif-Des-Armes-&#192;-Feu.html&quot; title=&quot;Tableau r&#233;capitulatif des armes &#224; feu&quot;&gt;tableau r&#233;capitulatif des armes &#224; feu&lt;/a&gt;.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt;Armes &#224; feu rudimentaires&lt;a class=&quot;headeranchor&quot; id=&quot;Armes_&#224;_feu_rudimentaires_4&quot; href=&quot;#Armes_&#224;_feu_rudimentaires_4&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&lt;h3 class=&quot;separator&quot;&gt;Armes &#224; feu &#224; une main&lt;a class=&quot;headeranchor&quot; id=&quot;Armes_&#224;_feu_&#224;_une_main_0&quot; href=&quot;#Armes_&#224;_feu_&#224;_une_main_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;&lt;table width=&quot;100%&quot;&gt;&lt;tr&gt;&lt;td width=&quot;50%&quot; style=&quot;padding-right:10px&quot;&gt;
&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Dague pistolet&quot; href=&quot;#Dague pistolet&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Dague pistolet.&lt;/b&gt; Combinant un &lt;a class=&quot;pagelink&quot; href=&quot;Pistolet-De-Poche-(Arme).html&quot; title=&quot;Pistolet de poche&quot;&gt;pistolet de poche&lt;/a&gt; avec une lame, la dague pistolet peut &#234;tre utilis&#233;e comme l’une ou l’autre de ces armes. Du fait de sa configuration peu pratique, le personnage ne b&#233;n&#233;ficie d’aucun des bonus qu’accordent ind&#233;pendamment ces deux armes aux tests d’&lt;a class=&quot;pagelink&quot; href=&quot;Escamotage.html&quot; title=&quot;Escamotage&quot;&gt;Escamotage&lt;/a&gt;. La dague pistolet est consid&#233;r&#233;e comme une &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armes#Armedouble.html&quot; title=&quot;arme double&quot;&gt;arme double&lt;/a&gt; en ce qui concerne la cr&#233;ation de versions &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armes#Armesmaitre.html&quot; title=&quot;arme de ma&#238;tre&quot;&gt;de ma&#238;tre&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Armes-Magiques.html&quot; title=&quot;Les armes magiques&quot;&gt;magique&lt;/a&gt; de cette arme. Si l’arme est bris&#233;e, l’arme &#224; feu et la dague sont consid&#233;r&#233;es comme &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Bris&#233;.html&quot; title=&quot;Bris&#233;&quot;&gt;bris&#233;es&lt;/a&gt;. La dague pistolet se charge d’une &lt;a class=&quot;pagelink&quot; href=&quot;Balle-Darme-&#192;-Feu-(Arme).html&quot; title=&quot;Balle d&amp;#39;arme &#224; feu (1)&quot;&gt;balle&lt;/a&gt; et d’une dose de &lt;a class=&quot;pagelink&quot; href=&quot;Poudre-Noire-(Arme).html&quot; title=&quot;Poudre noire&quot;&gt;poudre noire&lt;/a&gt; ou d’une &lt;a class=&quot;pagelink&quot; href=&quot;Cartouche-Alchimique-(Arme).html&quot; title=&quot;Cartouche alchimique&quot;&gt;cartouche alchimique&lt;/a&gt;. Il s’agit d’une &lt;a class=&quot;pagelink&quot; href=&quot;Armes-&#192;-Feu.html#CATEGORIE&quot; title=&quot;Caract&#233;ristiques des armes &#224; feu&quot;&gt;arme &#224; feu rudimentaire&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Pistolet&quot; href=&quot;#Pistolet&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Pistolet.&lt;/b&gt; Ce pistolet de base &#224; tir simple est l’une des armes &#224; feu les plus courantes, bien que dans la plupart des campagnes il soit encore suffisamment rare pour susciter l’envie ou la curiosit&#233; de beaucoup. Il peut prendre diff&#233;rentes formes, des chefs-d’oeuvre grandement d&#233;cor&#233;s en forme de dragons soufflant du feu, aux pistolets plus communs &#224; crosse en bois, en passant par le simple tube de m&#233;tal pourvu d’un m&#233;canisme de d&#233;tente. Le pistolet se charge avec une &lt;a class=&quot;pagelink&quot; href=&quot;Balle-Darme-&#192;-Feu-(Arme).html&quot; title=&quot;Balle d&amp;#39;arme &#224; feu (1)&quot;&gt;balle&lt;/a&gt; et une dose de &lt;a class=&quot;pagelink&quot; href=&quot;Poudre-Noire-(Arme).html&quot; title=&quot;Poudre noire&quot;&gt;poudre noire&lt;/a&gt; ou une &lt;a class=&quot;pagelink&quot; href=&quot;Cartouche-Alchimique-(Arme).html&quot; title=&quot;Cartouche alchimique&quot;&gt;cartouche alchimique&lt;/a&gt;. Il s’agit d’une &lt;a class=&quot;pagelink&quot; href=&quot;Armes-&#192;-Feu.html#CATEGORIE&quot; title=&quot;Caract&#233;ristiques des armes &#224; feu&quot;&gt;arme &#224; feu rudimentaire&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Pistolet &#224; double canon&quot; href=&quot;#Pistolet &#224; double canon&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Pistolet &#224; double canon.&lt;/b&gt; Ce &lt;a class=&quot;pagelink&quot; href=&quot;Pistolet-(Arme).html&quot; title=&quot;Pistolet&quot;&gt;pistolet&lt;/a&gt; a deux canons parall&#232;les. On peut tirer avec chaque canon ind&#233;pendamment, en deux actions s&#233;par&#233;es, ou tirer avec les deux en m&#234;me temps par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt; (une action d&#39;attaque). Si les deux canons tirent en m&#234;me temps, ils doivent cibler la m&#234;me cr&#233;ature ou le m&#234;me objet, mais le pistolet est alors extr&#234;mement impr&#233;cis et impose un malus de -4 &#224; chaque tir. Il s’agit d’une &lt;a class=&quot;pagelink&quot; href=&quot;Armes-&#192;-Feu.html#CATEGORIE&quot; title=&quot;Caract&#233;ristiques des armes &#224; feu&quot;&gt;arme &#224; feu rudimentaire&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Pistolet canne-&#233;p&#233;e&quot; href=&quot;#Pistolet canne-&#233;p&#233;e&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Pistolet canne-&#233;p&#233;e.&lt;/b&gt; Cette arme est un m&#233;lange entre le &lt;a class=&quot;pagelink&quot; href=&quot;Pistolet-De-Poche-(Arme).html&quot; title=&quot;Pistolet de poche&quot;&gt;pistolet de poche&lt;/a&gt; et la &lt;a class=&quot;pagelink&quot; href=&quot;Canne-&#201;p&#233;e-(Arme).html&quot; title=&quot;Canne &#233;p&#233;e&quot;&gt;canne &#233;p&#233;e&lt;/a&gt;. Le pistolet canne-&#233;p&#233;e est consid&#233;r&#233; comme une &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armes#Armedouble.html&quot; title=&quot;arme double&quot;&gt;arme double&lt;/a&gt; en ce qui concerne la cr&#233;ation de versions &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armes#Armesmaitre.html&quot; title=&quot;arme de ma&#238;tre&quot;&gt;de ma&#238;tre&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Armes-Magiques.html&quot; title=&quot;Les armes magiques&quot;&gt;magiques&lt;/a&gt;. Le pistolet rend l’arme plus difficile &#224; cacher. Un observateur doit r&#233;ussir un test de &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; 15 pour r&#233;aliser que le pistolet canne-&#233;p&#233;e est une arme, non une simple canne. Ce &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; baisse de 5 si l’observateur peut manipuler l’arme. Le pistolet canne-&#233;p&#233;e se charge avec une &lt;a class=&quot;pagelink&quot; href=&quot;Balle-Darme-&#192;-Feu-(Arme).html&quot; title=&quot;Balle d&amp;#39;arme &#224; feu (1)&quot;&gt;balle&lt;/a&gt; et une dose de &lt;a class=&quot;pagelink&quot; href=&quot;Poudre-Noire-(Arme).html&quot; title=&quot;Poudre noire&quot;&gt;poudre noire&lt;/a&gt; ou une &lt;a class=&quot;pagelink&quot; href=&quot;Cartouche-Alchimique-(Arme).html&quot; title=&quot;Cartouche alchimique&quot;&gt;cartouche alchimique&lt;/a&gt;. Il faut d&#233;gainer la partie &#233;p&#233;e de l’arme pour charger la partie pistolet de l’arme. Il s’agit d’une &lt;a class=&quot;pagelink&quot; href=&quot;Armes-&#192;-Feu.html#CATEGORIE&quot; title=&quot;Caract&#233;ristiques des armes &#224; feu&quot;&gt;arme &#224; feu rudimentaire&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;/td&gt;&lt;td width=&quot;50%&quot; style=&quot;vertical-align:top; border-left:solid 1px #002564; padding-left:10px&quot;&gt;
&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Pistolet de poche&quot; href=&quot;#Pistolet de poche&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Pistolet de poche.&lt;/b&gt; Quoique moins puissant que les autres armes &#224; feu de plus grande taille, ce &lt;a class=&quot;pagelink&quot; href=&quot;Pistolet-(Arme).html&quot; title=&quot;Pistolet&quot;&gt;pistolet&lt;/a&gt; est suffisamment petit pour se dissimuler facilement sous une veste ou un manteau. Le personnage b&#233;n&#233;ficie d’un bonus de +2 &#224; ses tests d’&lt;a class=&quot;pagelink&quot; href=&quot;Escamotage.html&quot; title=&quot;Escamotage&quot;&gt;Escamotage&lt;/a&gt; pour dissimuler un pistolet de poche sur lui. Le pistolet de poche se charge d’une &lt;a class=&quot;pagelink&quot; href=&quot;Balle-Darme-&#192;-Feu-(Arme).html&quot; title=&quot;Balle d&amp;#39;arme &#224; feu (1)&quot;&gt;balle&lt;/a&gt; et d’une dose de &lt;a class=&quot;pagelink&quot; href=&quot;Poudre-Noire-(Arme).html&quot; title=&quot;Poudre noire&quot;&gt;poudre noire&lt;/a&gt; ou d’une &lt;a class=&quot;pagelink&quot; href=&quot;Cartouche-Alchimique-(Arme).html&quot; title=&quot;Cartouche alchimique&quot;&gt;cartouche alchimique&lt;/a&gt;. Il s’agit d’une &lt;a class=&quot;pagelink&quot; href=&quot;Armes-&#192;-Feu.html#CATEGORIE&quot; title=&quot;Caract&#233;ristiques des armes &#224; feu&quot;&gt;arme &#224; feu rudimentaire&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Pistolet dragon&quot; href=&quot;#Pistolet dragon&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Pistolet dragon.&lt;/b&gt; Tel un &lt;a class=&quot;pagelink&quot; href=&quot;Tromblon-(Arme).html&quot; title=&quot;Tromblon&quot;&gt;tromblon&lt;/a&gt; miniature, le pistolet dragon tire des plombs ou des balles gr&#226;ce &#224; son canon &#233;vas&#233;. Le pistolet dragon tire un c&#244;ne de plombs de 4,50 m&#232;tres et a un &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armes#Facteurdeportee.html&quot; title=&quot;facteur de port&#233;e&quot;&gt;facteur de port&#233;e&lt;/a&gt; de 3 m&#232;tres lorsqu’il tire une balle. Le pistolet dragon se charge d’une &lt;a class=&quot;pagelink&quot; href=&quot;Balle-Darme-&#192;-Feu-(Arme).html&quot; title=&quot;Balle d&amp;#39;arme &#224; feu (1)&quot;&gt;balle&lt;/a&gt; ou de &lt;a class=&quot;pagelink&quot; href=&quot;Plombs-(Arme).html&quot; title=&quot;Plombs (poign&#233;e)&quot;&gt;plombs&lt;/a&gt; avec une dose de &lt;a class=&quot;pagelink&quot; href=&quot;Poudre-Noire-(Arme).html&quot; title=&quot;Poudre noire&quot;&gt;poudre noire&lt;/a&gt; ou d’une &lt;a class=&quot;pagelink&quot; href=&quot;Cartouche-Alchimique-(Arme).html&quot; title=&quot;Cartouche alchimique&quot;&gt;cartouche alchimique&lt;/a&gt; (avec des balles ou des plombs). Il s’agit d’une &lt;a class=&quot;pagelink&quot; href=&quot;Armes-&#192;-Feu.html#CATEGORIE&quot; title=&quot;Caract&#233;ristiques des armes &#224; feu&quot;&gt;arme &#224; feu rudimentaire&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Poivri&#232;re&quot; href=&quot;#Poivri&#232;re&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Poivri&#232;re.&lt;/b&gt; Ce &lt;a class=&quot;pagelink&quot; href=&quot;Pistolet-(Arme).html&quot; title=&quot;Pistolet&quot;&gt;pistolet&lt;/a&gt; a six canons au lieu d’un. On peut faire tourner le barillet rapidement entre les tirs (une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Libre.html&quot; title=&quot;Action libre&quot;&gt;action libre&lt;/a&gt; n&#233;cessitant d’avoir une main libre) pour tirer les six balles avant de recharger l’arme. Chaque canon de la poivri&#232;re se charge soit d’une &lt;a class=&quot;pagelink&quot; href=&quot;Balle-Darme-&#192;-Feu-(Arme).html&quot; title=&quot;Balle d&amp;#39;arme &#224; feu (1)&quot;&gt;balle&lt;/a&gt; et d’une dose de &lt;a class=&quot;pagelink&quot; href=&quot;Poudre-Noire-(Arme).html&quot; title=&quot;Poudre noire&quot;&gt;poudre noire&lt;/a&gt;, soit d’une &lt;a class=&quot;pagelink&quot; href=&quot;Cartouche-Alchimique-(Arme).html&quot; title=&quot;Cartouche alchimique&quot;&gt;cartouche alchimique&lt;/a&gt;. Il s’agit d’une &lt;a class=&quot;pagelink&quot; href=&quot;Armes-&#192;-Feu.html#CATEGORIE&quot; title=&quot;Caract&#233;ristiques des armes &#224; feu&quot;&gt;arme &#224; feu rudimentaire&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Targe pistolet&quot; href=&quot;#Targe pistolet&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Targe pistolet.&lt;/b&gt; La fa&#231;ade de cette &lt;a class=&quot;pagelink&quot; href=&quot;Targe-(Armure).html&quot; title=&quot;Targe&quot;&gt;targe&lt;/a&gt; est &#233;quip&#233;e d’un petit &lt;a class=&quot;pagelink&quot; href=&quot;Pistolet-&#192;-Double-Canon-(Arme).html&quot; title=&quot;Pistolet &#224; double canon&quot;&gt;pistolet &#224; double canon&lt;/a&gt; avec lequel on peut tirer tout en portant la targe. Contrairement au pistolet &#224; double canon, on ne peut tirer qu’avec un seul canon &#224; la fois. Le personnage doit enlever la targe pour recharger le pistolet. Chacun des canons de la targe se charge d’une &lt;a class=&quot;pagelink&quot; href=&quot;Balle-Darme-&#192;-Feu-(Arme).html&quot; title=&quot;Balle d&amp;#39;arme &#224; feu (1)&quot;&gt;balle&lt;/a&gt; et d’une dose de &lt;a class=&quot;pagelink&quot; href=&quot;Poudre-Noire-(Arme).html&quot; title=&quot;Poudre noire&quot;&gt;poudre noire&lt;/a&gt; ou d’une &lt;a class=&quot;pagelink&quot; href=&quot;Cartouche-Alchimique-(Arme).html&quot; title=&quot;Cartouche alchimique&quot;&gt;cartouche alchimique&lt;/a&gt;. En raison de sa construction peu commode, la targe pistolet est toujours consid&#233;r&#233;e comme une &lt;a class=&quot;pagelink&quot; href=&quot;Actions-Sp&#233;ciales.html#COMBAT2ARMES&quot; title=&quot;Actions sp&#233;ciales&quot;&gt;arme secondaire&lt;/a&gt;. Il s’agit d’une &lt;a class=&quot;pagelink&quot; href=&quot;Armes-&#192;-Feu.html#CATEGORIE&quot; title=&quot;Caract&#233;ristiques des armes &#224; feu&quot;&gt;arme &#224; feu rudimentaire&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Armes &#224; feu &#224; deux mains&lt;a class=&quot;headeranchor&quot; id=&quot;Armes_&#224;_feu_&#224;_deux_mains_1&quot; href=&quot;#Armes_&#224;_feu_&#224;_deux_mains_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;&lt;table width=&quot;100%&quot;&gt;&lt;tr&gt;&lt;td width=&quot;50%&quot; style=&quot;padding-right:10px&quot;&gt;
&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Couleuvrine&quot; href=&quot;#Couleuvrine&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Couleuvrine.&lt;/b&gt; La couleuvrine, aussi appel&#233;e bombarde &#224; main, se compose d’un simple tube &#224; canon lisse, scell&#233; &#224; l’une de ses extr&#233;mit&#233;s, &#224; l’exception d’un petit trou servant &#224; allumer une charge de poudre &#224; canon. Une pi&#232;ce de bois partiellement ench&#226;ss&#233;e dans le canon permet au personnage de la tenir sous son bras relativement facilement lorsqu’il la transporte. S’il tire sans support (comme un mur, une fen&#234;tre ou une barre), il subit un malus de -4 au &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jet d’attaque&lt;/a&gt; et tombe &#224; la renverse. La couleuvrine se charge de 4 doses de &lt;a class=&quot;pagelink&quot; href=&quot;Poudre-Noire-(Arme).html&quot; title=&quot;Poudre noire&quot;&gt;poudre noire&lt;/a&gt; et de mitraille (une &lt;a class=&quot;pagelink&quot; href=&quot;Plombs-(Arme).html&quot; title=&quot;Plombs (poign&#233;e)&quot;&gt;poign&#233;e de plombs&lt;/a&gt;). Notez que ces statistiques ne font qu’imiter les couleuvrines portables originales : leurs descendantes, plus grandes, sont consid&#233;r&#233;es comme des canons et sont trait&#233;es dans la partie des &lt;a class=&quot;pagelink&quot; href=&quot;Engins-De-Si&#232;ge.html&quot; title=&quot;Engins de si&#232;ge&quot;&gt;engins de si&#232;ge&lt;/a&gt;. Il s’agit d’une &lt;a class=&quot;pagelink&quot; href=&quot;Armes-&#192;-Feu.html#CATEGORIE&quot; title=&quot;Caract&#233;ristiques des armes &#224; feu&quot;&gt;arme &#224; feu rudimentaire&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Double arquebuse&quot; href=&quot;#Double arquebuse&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Double arquebuse.&lt;/b&gt; Ce fusil &#224; canon double utilise une paire de tourillons pour transformer le canon en un m&#233;canisme orientable attach&#233; au sommet d’un chariot l&#233;ger &#224; deux roues. Il faut une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Complexe.html&quot; title=&quot;Action complexe&quot;&gt;action complexe&lt;/a&gt; pour installer le chariot. Il a un pied arri&#232;re permettant au porteur de faire rouler l’engin et de le poser aussit&#244;t pour avoir plus de stabilit&#233; en combat. Contrairement aux autres armes &#224; feu &#224; deux mains, le personnage doit tirer &#224; l’arquebuse double lorsqu’elle est mont&#233;e sur son chariot seulement, sinon il re&#231;oit un malus de -4 &#224; ses &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jets d’attaque&lt;/a&gt; et le recul le fait tomber. Une cr&#233;ature de taille G ou plus grande peut tirer avec une double arquebuse plus petite qu’elle d’une cat&#233;gorie de taille sans &#234;tre oblig&#233;e de la poser sur un chariot, comme s’il s’agissait d’une &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armes#Armeadeuxmains.html&quot; title=&quot;arme &#224; deux mains&quot;&gt;arme &#224; deux mains normale&lt;/a&gt;, et sans risquer de tomber, mais elle re&#231;oit le malus normal li&#233; &#224; l’utilisation d’une &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armes.html#TAILLEARME&quot; title=&quot;Caract&#233;ristiques des armes&quot;&gt;arme de taille inappropri&#233;e&lt;/a&gt;. Il s’agit d’une &lt;a class=&quot;pagelink&quot; href=&quot;Armes-&#192;-Feu.html#CATEGORIE&quot; title=&quot;Caract&#233;ristiques des armes &#224; feu&quot;&gt;arme &#224; feu rudimentaire&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Hache mousquet&quot; href=&quot;#Hache mousquet&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Hache mousquet.&lt;/b&gt; Ce petit mousquet est &#233;quip&#233; d’une lame de hache fix&#233;e au bout du canon. Il peut servir &#224; la fois de &lt;a class=&quot;pagelink&quot; href=&quot;Mousquet-(Arme).html&quot; title=&quot;Mousquet&quot;&gt;mousquet&lt;/a&gt; et de &lt;a class=&quot;pagelink&quot; href=&quot;Hache-Darmes-(Arme).html&quot; title=&quot;Hache d&amp;#39;armes&quot;&gt;hache d’armes&lt;/a&gt;. Il est consid&#233;r&#233; comme une &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armes#Armedouble.html&quot; title=&quot;arme double&quot;&gt;arme double&lt;/a&gt; en ce qui concerne la cr&#233;ation de versions &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armes#Armesmaitre.html&quot; title=&quot;arme de ma&#238;tre&quot;&gt;de ma&#238;tre&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Armes-Magiques.html&quot; title=&quot;Les armes magiques&quot;&gt;magiques&lt;/a&gt;. Si cette arme &#224; feu est bris&#233;e, les composants de l’arme &#224; feu et la hache sont consid&#233;r&#233;s comme &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Bris&#233;.html&quot; title=&quot;Bris&#233;&quot;&gt;bris&#233;s&lt;/a&gt;. La hache mousquet utilise soit une &lt;a class=&quot;pagelink&quot; href=&quot;Balle-Darme-&#192;-Feu-(Arme).html&quot; title=&quot;Balle d&amp;#39;arme &#224; feu (1)&quot;&gt;balle&lt;/a&gt; et une seule dose de &lt;a class=&quot;pagelink&quot; href=&quot;Poudre-Noire-(Arme).html&quot; title=&quot;Poudre noire&quot;&gt;poudre noire&lt;/a&gt;, soit une &lt;a class=&quot;pagelink&quot; href=&quot;Cartouche-Alchimique-(Arme).html&quot; title=&quot;Cartouche alchimique&quot;&gt;cartouche alchimique&lt;/a&gt; comme munition. Il s’agit d’une &lt;a class=&quot;pagelink&quot; href=&quot;Armes-&#192;-Feu.html#CATEGORIE&quot; title=&quot;Caract&#233;ristiques des armes &#224; feu&quot;&gt;arme &#224; feu rudimentaire&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Lance-flamme&quot; href=&quot;#Lance-flamme&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Lance-flamme.&lt;/b&gt; Cette arme primitive n’est rien de plus qu’un long tube qui, lorsqu’il est allum&#233;, projette une courte flamme et une &lt;a class=&quot;pagelink&quot; href=&quot;Javeline-(Arme).html&quot; title=&quot;Javeline&quot;&gt;javeline&lt;/a&gt;. Contrairement aux autres armes &#224; feu, le lance-flamme est tr&#232;s impr&#233;cis et d&#233;pend de la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt; au lieu de la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA de contact&lt;/a&gt;. Le lance-flamme est toujours consid&#233;r&#233; comme &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Bris&#233;.html&quot; title=&quot;Bris&#233;&quot;&gt;bris&#233;&lt;/a&gt; quand il s’agit de d&#233;terminer les effets d’un &lt;a class=&quot;pagelink&quot; href=&quot;Armes-&#192;-Feu#Enrayement.html&quot; title=&quot;enrayement&quot;&gt;enrayement&lt;/a&gt;. Le lance-flamme se charge d’une javeline et de deux doses de &lt;a class=&quot;pagelink&quot; href=&quot;Poudre-Noire-(Arme).html&quot; title=&quot;Poudre noire&quot;&gt;poudre noire&lt;/a&gt;. Il s’agit d’une &lt;a class=&quot;pagelink&quot; href=&quot;Armes-&#192;-Feu.html#CATEGORIE&quot; title=&quot;Caract&#233;ristiques des armes &#224; feu&quot;&gt;arme &#224; feu rudimentaire&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;/td&gt;&lt;td width=&quot;50%&quot; style=&quot;vertical-align:top; border-left:solid 1px #002564; padding-left:10px&quot;&gt;
&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Marteau mousquet&quot; href=&quot;#Marteau mousquet&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Marteau mousquet.&lt;/b&gt; Ce mousquet est &#233;quip&#233; d’une t&#234;te de marteau de guerre plac&#233;e au bout du canon, ce qui permet de l’utiliser &#224; la fois comme un &lt;a class=&quot;pagelink&quot; href=&quot;Mousquet-(Arme).html&quot; title=&quot;Mousquet&quot;&gt;mousquet&lt;/a&gt; et comme un &lt;a class=&quot;pagelink&quot; href=&quot;Marteau-De-Guerre-(Arme).html&quot; title=&quot;Marteau de guerre&quot;&gt;marteau de guerre&lt;/a&gt;. Il est consid&#233;r&#233; comme une &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armes#Armedouble.html&quot; title=&quot;arme double&quot;&gt;arme double&lt;/a&gt; en ce qui concerne la cr&#233;ation de versions &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armes#Armesmaitre.html&quot; title=&quot;arme de ma&#238;tre&quot;&gt;de ma&#238;tre&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Armes-Magiques.html&quot; title=&quot;Les armes magiques&quot;&gt;magiques&lt;/a&gt;. Si l’arme &#224; feu est bris&#233;e, l’arme &#224; feu et le marteau de guerre sont consid&#233;r&#233;s comme &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Bris&#233;.html&quot; title=&quot;Bris&#233;&quot;&gt;bris&#233;s&lt;/a&gt;. Le marteau mousquet se charge soit avec une balle et une dose de poudre noire, soit avec une cartouche alchimique. Il s’agit d’une &lt;a class=&quot;pagelink&quot; href=&quot;Armes-&#192;-Feu.html#CATEGORIE&quot; title=&quot;Caract&#233;ristiques des armes &#224; feu&quot;&gt;arme &#224; feu rudimentaire&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Mousquet&quot; href=&quot;#Mousquet&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Mousquet.&lt;/b&gt; Cette arme &#224; canon long a une bien plus grande port&#233;e que le &lt;a class=&quot;pagelink&quot; href=&quot;Pistolet-(Arme).html&quot; title=&quot;Pistolet&quot;&gt;pistolet&lt;/a&gt;. Le mousquet se charge d’une &lt;a class=&quot;pagelink&quot; href=&quot;Balle-Darme-&#192;-Feu-(Arme).html&quot; title=&quot;Balle d&amp;#39;arme &#224; feu (1)&quot;&gt;balle&lt;/a&gt; et d’une dose de &lt;a class=&quot;pagelink&quot; href=&quot;Poudre-Noire-(Arme).html&quot; title=&quot;Poudre noire&quot;&gt;poudre noire&lt;/a&gt; ou d’une &lt;a class=&quot;pagelink&quot; href=&quot;Cartouche-Alchimique-(Arme).html&quot; title=&quot;Cartouche alchimique&quot;&gt;cartouche alchimique&lt;/a&gt;. Il s’agit d’une &lt;a class=&quot;pagelink&quot; href=&quot;Armes-&#192;-Feu.html#CATEGORIE&quot; title=&quot;Caract&#233;ristiques des armes &#224; feu&quot;&gt;arme &#224; feu rudimentaire&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Mousquet &#224; double canon&quot; href=&quot;#Mousquet &#224; double canon&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Mousquet &#224; double canon.&lt;/b&gt; Ce &lt;a class=&quot;pagelink&quot; href=&quot;Mousquet-(Arme).html&quot; title=&quot;Mousquet&quot;&gt;mousquet&lt;/a&gt; a deux canons parall&#232;les. On peut tirer avec chacun d’eux ind&#233;pendamment en deux actions s&#233;par&#233;es ou tirer avec les deux en m&#234;me temps par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt; (une action d&#39;attaque). Si les deux canons tirent ensemble, ils doivent cibler la m&#234;me cr&#233;ature ou le m&#234;me objet. L’arme est alors extr&#234;mement impr&#233;cise et donne un malus de -4 &#224; chaque tir. Chaque canon du mousquet &#224; double canon se charge soit d’une &lt;a class=&quot;pagelink&quot; href=&quot;Balle-Darme-&#192;-Feu-(Arme).html&quot; title=&quot;Balle d&amp;#39;arme &#224; feu (1)&quot;&gt;balle&lt;/a&gt; et d&#39;une dose de &lt;a class=&quot;pagelink&quot; href=&quot;Poudre-Noire-(Arme).html&quot; title=&quot;Poudre noire&quot;&gt;poudre noire&lt;/a&gt;, soit d&#39;une &lt;a class=&quot;pagelink&quot; href=&quot;Cartouche-Alchimique-(Arme).html&quot; title=&quot;Cartouche alchimique&quot;&gt;cartouche alchimique&lt;/a&gt;. Il s’agit d’une &lt;a class=&quot;pagelink&quot; href=&quot;Armes-&#192;-Feu.html#CATEGORIE&quot; title=&quot;Caract&#233;ristiques des armes &#224; feu&quot;&gt;arme &#224; feu rudimentaire&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Tromblon&quot; href=&quot;#Tromblon&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Tromblon.&lt;/b&gt; Cette arme tire des plombs ou une balle avec son canon en forme de trompette, ce qui en fait une arme efficace pour la chasse ou pour se d&#233;fendre en combat rapproch&#233;. Le tromblon tire dans un c&#244;ne de 4,50 m&#232;tres de long quand il tire des plombs. Quand il tire une balle, il a un &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armes#Facteurdeportee.html&quot; title=&quot;facteur de port&#233;e&quot;&gt;facteur de port&#233;e&lt;/a&gt; de 3 m&#232;tres. Le tromblon se charge d’une &lt;a class=&quot;pagelink&quot; href=&quot;Balle-Darme-&#192;-Feu-(Arme).html&quot; title=&quot;Balle d&amp;#39;arme &#224; feu (1)&quot;&gt;balle&lt;/a&gt; ou de &lt;a class=&quot;pagelink&quot; href=&quot;Plombs-(Arme).html&quot; title=&quot;Plombs (poign&#233;e)&quot;&gt;plombs&lt;/a&gt;, avec une seule dose de &lt;a class=&quot;pagelink&quot; href=&quot;Poudre-Noire-(Arme).html&quot; title=&quot;Poudre noire&quot;&gt;poudre noire&lt;/a&gt; ou d’une &lt;a class=&quot;pagelink&quot; href=&quot;Cartouche-Alchimique-(Arme).html&quot; title=&quot;Cartouche alchimique&quot;&gt;cartouche alchimique&lt;/a&gt;. Il s’agit d’une &lt;a class=&quot;pagelink&quot; href=&quot;Armes-&#192;-Feu.html#CATEGORIE&quot; title=&quot;Caract&#233;ristiques des armes &#224; feu&quot;&gt;arme &#224; feu rudimentaire&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt;Armes &#224; feu &#233;volu&#233;es&lt;a class=&quot;headeranchor&quot; id=&quot;Armes_&#224;_feu_&#233;volu&#233;es_5&quot; href=&quot;#Armes_&#224;_feu_&#233;volu&#233;es_5&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&lt;h3 class=&quot;separator&quot;&gt;Armes &#224; feu &#224; une main&lt;a class=&quot;headeranchor&quot; id=&quot;Armes_&#224;_feu_&#224;_une_main_2&quot; href=&quot;#Armes_&#224;_feu_&#224;_une_main_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;&lt;table width=&quot;100%&quot;&gt;&lt;tr&gt;&lt;td width=&quot;50%&quot; style=&quot;padding-right:10px&quot;&gt;
&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Revolver&quot; href=&quot;#Revolver&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Revolver.&lt;/b&gt; Le revolver est un &lt;a class=&quot;pagelink&quot; href=&quot;Pistolet-(Arme).html&quot; title=&quot;Pistolet&quot;&gt;pistolet&lt;/a&gt; avec un barillet rotatif &#224; six chambres. Chaque chambre peut contenir une &lt;a class=&quot;pagelink&quot; href=&quot;Cartouche-En-M&#233;tal-(Arme).html&quot; title=&quot;Cartouche en m&#233;tal&quot;&gt;cartouche en m&#233;tal&lt;/a&gt; et, lorsqu’une cartouche est tir&#233;e, le cylindre tourne automatiquement (pas besoin d’avoir une main libre ou de faire une action), pr&#233;parant la chambre suivante pour le prochain tir. Le revolver se charge avec des cartouches en m&#233;tal. Il s’agit d’une &lt;a class=&quot;pagelink&quot; href=&quot;Armes-&#192;-Feu.html#CATEGORIE&quot; title=&quot;Caract&#233;ristiques des armes &#224; feu&quot;&gt;arme &#224; feu &#233;volu&#233;e&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;/td&gt;&lt;td width=&quot;50%&quot; style=&quot;vertical-align:top; border-left:solid 1px #002564; padding-left:10px&quot;&gt;&lt;br /&gt;&lt;br /&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Armes &#224; feu &#224; deux mains&lt;a class=&quot;headeranchor&quot; id=&quot;Armes_&#224;_feu_&#224;_deux_mains_3&quot; href=&quot;#Armes_&#224;_feu_&#224;_deux_mains_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;&lt;table width=&quot;100%&quot;&gt;&lt;tr&gt;&lt;td width=&quot;50%&quot; style=&quot;padding-right:10px&quot;&gt;
&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Fusil&quot; href=&quot;#Fusil&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Fusil.&lt;/b&gt; Cette &#233;volution du &lt;a class=&quot;pagelink&quot; href=&quot;Mousquet-(Arme).html&quot; title=&quot;Mousquet&quot;&gt;mousquet&lt;/a&gt; pr&#233;sente un canon stri&#233; qui donne &#224; la balle un mouvement en spirale lorsqu’elle est tir&#233;e, la stabilisant et l’emp&#234;chant de voler cul par-dessus t&#234;te, contrairement &#224; ce qui arrive aux projectiles des armes &#224; feu moins &#233;volu&#233;es. De ce fait, le fusil peut tirer bien plus loin et avec une plus grande pr&#233;cision que les armes &#224; feu rudimentaires &#224; canon long. Le fusil se charge avec des &lt;a class=&quot;pagelink&quot; href=&quot;Cartouche-En-M&#233;tal-(Arme).html&quot; title=&quot;Cartouche en m&#233;tal&quot;&gt;cartouches en m&#233;tal&lt;/a&gt;. Il s’agit d’une &lt;a class=&quot;pagelink&quot; href=&quot;Armes-&#192;-Feu.html#CATEGORIE&quot; title=&quot;Caract&#233;ristiques des armes &#224; feu&quot;&gt;arme &#224; feu &#233;volu&#233;e&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Fusil de chasse&quot; href=&quot;#Fusil de chasse&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Fusil de chasse.&lt;/b&gt; Cette version &#233;volu&#233;e du &lt;a class=&quot;pagelink&quot; href=&quot;Tromblon-(Arme).html&quot; title=&quot;Tromblon&quot;&gt;tromblon&lt;/a&gt; tire des plombs dans un c&#244;ne de 9 m&#232;tres de long et a un &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armes#Facteurdeportee.html&quot; title=&quot;facteur de port&#233;e&quot;&gt;facteur de port&#233;e&lt;/a&gt; de 6 m&#232;tres lorsqu’il tire une balle (on parle souvent de pruneau). Les fusils de chasse peuvent &#234;tre simples et fonctionnels comme ils peuvent &#234;tre de v&#233;ritables chefs-d’oeuvre, avec des gravures et des incrustations sur le f&#251;t et la culasse. Ceux qu’utilise la haute soci&#233;t&#233; sont souvent d&#233;cor&#233;s d’images de gibier, d’armoiries familiales ou de la marque &#233;labor&#233;e du cr&#233;ateur. Le fusil de chasse se charge avec des &lt;a class=&quot;pagelink&quot; href=&quot;Cartouche-En-M&#233;tal-(Arme).html&quot; title=&quot;Cartouche en m&#233;tal&quot;&gt;cartouches en m&#233;tal&lt;/a&gt; (charg&#233;es d&#39;une &lt;a class=&quot;pagelink&quot; href=&quot;Balle-Darme-&#192;-Feu-(Arme).html&quot; title=&quot;Balle d&amp;#39;arme &#224; feu (1)&quot;&gt;balle&lt;/a&gt; ou de &lt;a class=&quot;pagelink&quot; href=&quot;Plombs-(Arme).html&quot; title=&quot;Plombs (poign&#233;e)&quot;&gt;plombs&lt;/a&gt;). Il s’agit d’une &lt;a class=&quot;pagelink&quot; href=&quot;Armes-&#192;-Feu.html#CATEGORIE&quot; title=&quot;Caract&#233;ristiques des armes &#224; feu&quot;&gt;arme &#224; feu &#233;volu&#233;e&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;/td&gt;&lt;td width=&quot;50%&quot; style=&quot;vertical-align:top; border-left:solid 1px #002564; padding-left:10px&quot;&gt;
&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Fusil de chasse &#224; double canon&quot; href=&quot;#Fusil de chasse &#224; double canon&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Fusil de chasse &#224; double canon.&lt;/b&gt; Ce &lt;a class=&quot;pagelink&quot; href=&quot;Fusil-(Arme).html&quot; title=&quot;Fusil&quot;&gt;fusil&lt;/a&gt; &#224; canons jumeaux peut tirer avec un seul canon &#224; la fois ou avec les deux en m&#234;me temps par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt; (une action d&#39;attaque). Les tirs doubles avec des balles sont impr&#233;cis, chaque attaque subissant un malus de -4. Un tir double avec des balles permet de cibler une seule cr&#233;ature et augmente les d&#233;g&#226;ts de chaque canon. Ils passent &#224; 2d6 points (taille P) ou &#224; 2d8 points (taille M) pour un total de 4d6 ou de 4d8 points de d&#233;g&#226;ts. Le fusil de chasse &#224; canon double se charge avec des &lt;a class=&quot;pagelink&quot; href=&quot;Cartouche-En-M&#233;tal-(Arme).html&quot; title=&quot;Cartouche en m&#233;tal&quot;&gt;cartouches en m&#233;tal&lt;/a&gt; (charg&#233;es d&#39;une &lt;a class=&quot;pagelink&quot; href=&quot;Balle-Darme-&#192;-Feu-(Arme).html&quot; title=&quot;Balle d&amp;#39;arme &#224; feu (1)&quot;&gt;balle&lt;/a&gt; ou de &lt;a class=&quot;pagelink&quot; href=&quot;Plombs-(Arme).html&quot; title=&quot;Plombs (poign&#233;e)&quot;&gt;plombs&lt;/a&gt;). Il s’agit d’une &lt;a class=&quot;pagelink&quot; href=&quot;Armes-&#192;-Feu.html#CATEGORIE&quot; title=&quot;Caract&#233;ristiques des armes &#224; feu&quot;&gt;arme &#224; feu &#233;volu&#233;e&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Fusil poivri&#232;re&quot; href=&quot;#Fusil poivri&#232;re&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Fusil poivri&#232;re.&lt;/b&gt; Les quatre canons de ce &lt;a class=&quot;pagelink&quot; href=&quot;Fusil-(Arme).html&quot; title=&quot;Fusil&quot;&gt;fusil&lt;/a&gt; sont fix&#233;s &#224; une chambre orientable que l’on peut rapidement tourner &#224; la main (une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Libre.html&quot; title=&quot;Action libre&quot;&gt;action libre&lt;/a&gt;) entre les tirs. Le fusil poivri&#232;re se charge avec des &lt;a class=&quot;pagelink&quot; href=&quot;Cartouche-En-M&#233;tal-(Arme).html&quot; title=&quot;Cartouche en m&#233;tal&quot;&gt;cartouches en m&#233;tal&lt;/a&gt;. Il s’agit d’une &lt;a class=&quot;pagelink&quot; href=&quot;Armes-&#192;-Feu.html#CATEGORIE&quot; title=&quot;Caract&#233;ristiques des armes &#224; feu&quot;&gt;arme &#224; feu &#233;volu&#233;e&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt;Munitions d&#39;armes &#224; feu&lt;a class=&quot;headeranchor&quot; id=&quot;Munitions_darmes_&#224;_feu_6&quot; href=&quot;#Munitions_darmes_&#224;_feu_6&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&lt;table width=&quot;100%&quot;&gt;&lt;tr&gt;&lt;td width=&quot;50%&quot; style=&quot;padding-right:10px&quot;&gt;
&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Balle darme &#224; feu&quot; href=&quot;#Balle darme &#224; feu&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Balle d&#39;arme &#224; feu (1).&lt;/b&gt; Munitions de la plupart des armes &#224; feu &#224; une et deux mains, les balles prennent g&#233;n&#233;ralement la forme de petites balles en plomb ou en un autre m&#233;tal. Trente balles p&#232;sent environ 0,25 grammes.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Balle gr&#234;l&#233;e&quot; href=&quot;#Balle gr&#234;l&#233;e&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Balle gr&#234;l&#233;e.&lt;/b&gt; Cette munition est creus&#233;e de petites d&#233;pressions dans lesquelles on peut placer des compos&#233;s empoisonn&#233;s sp&#233;cialement con&#231;us pour cet usage. Le compos&#233; est un d&#233;riv&#233; de toxine standard r&#233;duite par alchimie &#224; une forme solide. Il peut &#234;tre r&#233;alis&#233; &#224; partir de n’importe quel &lt;a class=&quot;pagelink&quot; href=&quot;Poisons.html&quot; title=&quot;Les poisons  &quot;&gt;poison&lt;/a&gt; de contact ou &#224; ingestion standard avec un test r&#233;ussi d’&lt;a class=&quot;pagelink&quot; href=&quot;Artisanat.html&quot; title=&quot;Artisanat&quot;&gt;Artisanat&lt;/a&gt; (poison) &#233;gal au &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; du poison +4. Le co&#251;t d’un compos&#233; empoisonn&#233; d&#233;j&#224; pr&#233;par&#233; est &#233;gal au prix de base du poison +20 po. Une fois que le compos&#233; est pr&#234;t, on peut le coller dans les trous de la munition o&#249; il durcit. Lorsque la balle est termin&#233;e, on peut la tirer avec une arme &#224; feu appropri&#233;e. Elle lib&#232;re son compos&#233; empoisonn&#233; sur la cible au moment de l’impact, mais le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; du poison est r&#233;duit de 2. Il est impossible d’utiliser une balle gr&#234;l&#233;e avec une &lt;a class=&quot;pagelink&quot; href=&quot;Cartouche-Alchimique-(Arme).html&quot; title=&quot;Cartouche alchimique&quot;&gt;cartouche alchimique&lt;/a&gt;. Le prix indiqu&#233; n’inclut pas le prix du poison.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Cartouche alchimique&quot; href=&quot;#Cartouche alchimique&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Cartouche alchimique.&lt;/b&gt; Une cartouche alchimique m&#234;le une poign&#233;e de poudre noire pr&#233;par&#233;e avec une balle ou des plombs. On y ajoute parfois des mat&#233;riaux plus exotiques avant d’envelopper le tout dans du papier ou dans un morceau de tissu scell&#233; avec de la cire d’abeille, du saindoux ou du suif. Il existe de nombreux types de cartouches alchimiques, le plus simple &#233;tant la cartouche en papier (un simple m&#233;lange de &lt;a class=&quot;pagelink&quot; href=&quot;Poudre-Noire-(Arme).html&quot; title=&quot;Poudre noire&quot;&gt;poudre noire&lt;/a&gt; et d’une &lt;a class=&quot;pagelink&quot; href=&quot;Balle-Darme-&#192;-Feu-(Arme).html&quot; title=&quot;Balle d&amp;#39;arme &#224; feu (1)&quot;&gt;balle&lt;/a&gt; ou de &lt;a class=&quot;pagelink&quot; href=&quot;Plombs-(Arme).html&quot; title=&quot;Plombs (poign&#233;e)&quot;&gt;plombs&lt;/a&gt;). Les cartouches alchimiques facilitent le rechargement des armes &#224; feu, r&#233;duisant son temps d’une cat&#233;gorie (une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Complexe.html&quot; title=&quot;Action complexe&quot;&gt;action complexe&lt;/a&gt; devient une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;, une action simple devient une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Mouvement.html&quot; title=&quot;Action de mouvement&quot;&gt;action de mouvement&lt;/a&gt; et une action de mouvement devient une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Libre.html&quot; title=&quot;Action libre&quot;&gt;action libre&lt;/a&gt;), mais elles sont souvent instables. La valeur d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Armes-&#192;-Feu#Enrayement.html&quot; title=&quot;enrayement&quot;&gt;enrayement&lt;/a&gt; d’une arme tirant une cartouche alchimique augmente comme indiqu&#233; pour chaque cartouche.
&lt;ul&gt;&lt;li&gt;&lt;i&gt;Cartouche d&#39;enchev&#234;trement.&lt;/i&gt; Ce m&#233;lange de poudre noire et de r&#233;sine trait&#233;e par alchimie pour survivre au tir se charge seulement dans les &lt;a class=&quot;pagelink&quot; href=&quot;Tromblon-(Arme).html&quot; title=&quot;Tromblon&quot;&gt;tromblons&lt;/a&gt;, les &lt;a class=&quot;pagelink&quot; href=&quot;Pistolet-Dragon-(Arme).html&quot; title=&quot;Pistolet dragon&quot;&gt;pistolets dragons&lt;/a&gt; et autres &lt;a class=&quot;pagelink&quot; href=&quot;Armes-&#192;-Feu.html#DISPERSION&quot; title=&quot;Caract&#233;ristiques des armes &#224; feu&quot;&gt;armes &#224; dispersion&lt;/a&gt;. Il inflige la moiti&#233; des d&#233;g&#226;ts &#224; ceux qui sont touch&#233;s par une attaque en c&#244;ne faite avec cette arme mais toutes les cr&#233;atures touch&#233;es doivent r&#233;ussir un jet de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;R&#233;flexes&quot;&gt;R&#233;flexes&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; 15 ou &#234;tre &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Enchev&#234;tr&#233;.html&quot; title=&quot;Enchev&#234;tr&#233;&quot;&gt;enchev&#234;tr&#233;es&lt;/a&gt; pendant 2d4 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt;. Les cartouches d’enchev&#234;trement augmentent la valeur d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Armes-&#192;-Feu#Enrayement.html&quot; title=&quot;enrayement&quot;&gt;enrayement&lt;/a&gt; de l’arme de 2.&lt;/li&gt;&lt;li&gt;&lt;i&gt;Cartouche de sel.&lt;/i&gt; Ce m&#233;lange de poudre noire et de cristaux de sel se charge dans un &lt;a class=&quot;pagelink&quot; href=&quot;Tromblon-(Arme).html&quot; title=&quot;Tromblon&quot;&gt;tromblon&lt;/a&gt;, un &lt;a class=&quot;pagelink&quot; href=&quot;Pistolet-Dragon-(Arme).html&quot; title=&quot;Pistolet dragon&quot;&gt;pistolet dragon&lt;/a&gt; ou une autre &lt;a class=&quot;pagelink&quot; href=&quot;Armes-&#192;-Feu.html#DISPERSION&quot; title=&quot;Caract&#233;ristiques des armes &#224; feu&quot;&gt;arme &#224; dispersion&lt;/a&gt;. Il inflige des d&#233;g&#226;ts &lt;a class=&quot;pagelink&quot; href=&quot;Blessures-Et-Mort.html#NONLETAL&quot; title=&quot;Blessures et mort&quot;&gt;non l&#233;taux&lt;/a&gt; plut&#244;t que des d&#233;g&#226;ts l&#233;taux et augmente la valeur d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Armes-&#192;-Feu#Enrayement.html&quot; title=&quot;enrayement&quot;&gt;enrayement&lt;/a&gt; de 1. Il ne peut &#234;tre utilis&#233; que pour les attaques en c&#244;ne des armes &#224; dispersion.&lt;/li&gt;&lt;li&gt;&lt;i&gt;Cartouche de souffle du dragon.&lt;/i&gt; Cette cartouche renferme un compos&#233; alchimique qui, lorsque la cartouche est tir&#233;e, g&#233;n&#232;re un c&#244;ne de feu plut&#244;t qu’une attaque normale d’arme &#224; feu de &lt;a class=&quot;pagelink&quot; href=&quot;Armes-&#192;-Feu.html#DISPERSION&quot; title=&quot;Caract&#233;ristiques des armes &#224; feu&quot;&gt;dispersion&lt;/a&gt; &#224; une main ou &#224; deux mains. Les flammes non-magiques infligent 2d6 points de d&#233;g&#226;ts de feu &#224; toutes les cibles pr&#233;sentes dans le c&#244;ne de dispersion de l’arme &#224; feu (&lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;R&#233;flexes&quot;&gt;R&#233;flexes&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; 15 1/2 d&#233;g&#226;ts). Ces cartouches ne peuvent pas &#234;tre utilis&#233;es avec les armes &#224; feu n’ayant pas l&#39;attribut dispersion. Cette munition imposant un &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jet de sauvegarde&lt;/a&gt; plut&#244;t qu’un &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jet d’attaque&lt;/a&gt;, les r&#232;gles d’&lt;a class=&quot;pagelink&quot; href=&quot;Armes-&#192;-Feu#Enrayement.html&quot; title=&quot;enrayement&quot;&gt;enrayement&lt;/a&gt; sont quelque peu diff&#233;rentes. Si le personnage fait un 1 naturel sur l’un de ses d&#233;s de d&#233;g&#226;ts, l’arme s’enraye.&lt;/li&gt;&lt;li&gt;&lt;i&gt;Cartouche en papier.&lt;/i&gt; Ce simple m&#233;lange de &lt;a class=&quot;pagelink&quot; href=&quot;Poudre-Noire-(Arme).html&quot; title=&quot;Poudre noire&quot;&gt;poudre noire&lt;/a&gt; et d’une &lt;a class=&quot;pagelink&quot; href=&quot;Balle-Darme-&#192;-Feu-(Arme).html&quot; title=&quot;Balle d&amp;#39;arme &#224; feu (1)&quot;&gt;balle&lt;/a&gt; ou de &lt;a class=&quot;pagelink&quot; href=&quot;Plombs-(Arme).html&quot; title=&quot;Plombs (poign&#233;e)&quot;&gt;plombs&lt;/a&gt; augmente la valeur d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Armes-&#192;-Feu#Enrayement.html&quot; title=&quot;enrayement&quot;&gt;enrayement&lt;/a&gt; de 1.&lt;/li&gt;&lt;li&gt;&lt;i&gt;Cartouche flamboyante.&lt;/i&gt; Lorsqu’une cartouche flamboyante touche sa cible, elle n’inflige que la moiti&#233; des d&#233;g&#226;ts normaux mais la cr&#233;ature touch&#233;e est &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Aveugl&#233;.html&quot; title=&quot;Aveugl&#233;&quot;&gt;aveugl&#233;e&lt;/a&gt; pendant 1 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Vigueur&quot;&gt;Vigueur&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; 15 r&#233;duit cet &#233;tat &#224; &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#&#201;bloui.html&quot; title=&quot;&#201;bloui&quot;&gt;&#233;bloui&lt;/a&gt;) et les cr&#233;atures dans un rayon de 6 m&#232;tres de l’explosion sont &#233;blouies pendant 1 round (Vigueur DD 15 annule cet effet). Les cartouches flamboyantes permettent aussi d’envoyer des signaux de d&#233;tresse. Tirer une cartouche flamboyante augmente la valeur d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Armes-&#192;-Feu#Enrayement.html&quot; title=&quot;enrayement&quot;&gt;enrayement&lt;/a&gt; de l’arme &#224; feu de 2 &#224; moins qu’elle ne soit tir&#233;e avec un &lt;a class=&quot;pagelink&quot; href=&quot;Tromblon-(Arme).html&quot; title=&quot;Tromblon&quot;&gt;tromblon&lt;/a&gt; ou un &lt;a class=&quot;pagelink&quot; href=&quot;Pistolet-Dragon-(Arme).html&quot; title=&quot;Pistolet dragon&quot;&gt;pistolet dragon&lt;/a&gt;, auquel cas la valeur d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Armes-&#192;-Feu#Enrayement.html&quot; title=&quot;enrayement&quot;&gt;enrayement&lt;/a&gt; de l’arme n’est augment&#233;e que de 1. Les cartouches flamboyantes ne peuvent servir qu’&#224; attaquer des cr&#233;atures isol&#233;es, elles ne fonctionnent pas pour les attaques en c&#244;ne d’une &lt;a class=&quot;pagelink&quot; href=&quot;Armes-&#192;-Feu.html#DISPERSION&quot; title=&quot;Caract&#233;ristiques des armes &#224; feu&quot;&gt;arme &#224; dispersion&lt;/a&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;/td&gt;&lt;td width=&quot;50%&quot; style=&quot;vertical-align:top; border-left:solid 1px #002564; padding-left:10px&quot;&gt;
&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Cartouche en m&#233;tal&quot; href=&quot;#Cartouche en m&#233;tal&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Cartouche en m&#233;tal.&lt;/b&gt; Ces variantes plus solides des &lt;a class=&quot;pagelink&quot; href=&quot;Cartouche-Alchimique-(Arme).html&quot; title=&quot;Cartouche alchimique&quot;&gt;cartouches alchimiques&lt;/a&gt; servent de munition aux &lt;a class=&quot;pagelink&quot; href=&quot;Armes-&#192;-Feu.html#CATEGORIE&quot; title=&quot;Caract&#233;ristiques des armes &#224; feu&quot;&gt;armes &#224; feu &#233;volu&#233;es&lt;/a&gt;. Elles peuvent contenir des &lt;a class=&quot;pagelink&quot; href=&quot;Balle-Darme-&#192;-Feu-(Arme).html&quot; title=&quot;Balle d&amp;#39;arme &#224; feu (1)&quot;&gt;balles&lt;/a&gt; ou des &lt;a class=&quot;pagelink&quot; href=&quot;Plombs-(Arme).html&quot; title=&quot;Plombs (poign&#233;e)&quot;&gt;plombs&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Plombs&quot; href=&quot;#Plombs&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Plombs (poign&#233;e).&lt;/b&gt; Une poign&#233;e de plombs, avec une dose de &lt;a class=&quot;pagelink&quot; href=&quot;Poudre-Noire-(Arme).html&quot; title=&quot;Poudre noire&quot;&gt;poudre noire&lt;/a&gt;, constitue la munition la plus couramment utilis&#233;e pour les armes &#224; feu &#224; &lt;a class=&quot;pagelink&quot; href=&quot;Armes-&#192;-Feu.html#DISPERSION&quot; title=&quot;Caract&#233;ristiques des armes &#224; feu&quot;&gt;dispersion&lt;/a&gt; &#224; une main et &#224; deux mains mais on peut les remplacer par des cailloux et autres petits bouts de mat&#233;riaux durs. Si le personnage utilise des munitions autres que les plombs ou les &lt;a class=&quot;pagelink&quot; href=&quot;Cartouche-Alchimique-(Arme).html&quot; title=&quot;Cartouche alchimique&quot;&gt;cartouches alchimiques&lt;/a&gt; alors qu’il effectue une attaque en c&#244;ne avec une arme &#224; dispersion, il augmente les risques d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Armes-&#192;-Feu#Enrayement.html&quot; title=&quot;enrayement&quot;&gt;enrayement&lt;/a&gt; de 1 (cette augmentation s’annule s’il revient aux munitions normales). Trente poign&#233;es de plombs p&#232;sent 0,25 grammes.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Poudre noire&quot; href=&quot;#Poudre noire&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Poudre noire (baril).&lt;/b&gt; La poudre noire est l’&#233;l&#233;ment explosif principal d’une arme &#224; feu. C’est elle qui lui permet de fonctionner, mais en grande quantit&#233;, ce mat&#233;riau alchimique peut &#233;galement &#234;tre tr&#232;s destructeur. Une seule dose de poudre noire suffit pour alimenter un simple tir sur la plupart des armes &#224; feu &#224; une main et &#224; deux mains, tandis qu’il faut 10 doses pour tirer au canon. La poudre noire est souvent conserv&#233;e et transport&#233;e dans des barils (contenant 100 doses), mais en telle quantit&#233;, la poudre en elle-m&#234;me devient dangereuse. Elle explose si elle est expos&#233;e au feu, &#224; l’&#233;lectricit&#233; ou &#224; une explosion li&#233;e &#224; un &lt;a class=&quot;pagelink&quot; href=&quot;Armes-&#192;-Feu#Enrayement.html&quot; title=&quot;enrayement&quot;&gt;enrayement&lt;/a&gt; : un seul baril explosant ainsi inflige 5d6 points de d&#233;g&#226;ts de feu &#224; quiconque se trouve dans un rayon de 6 m&#232;tres de l’explosion (&lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;R&#233;flexes&quot;&gt;R&#233;flexes&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; 15 1/2 d&#233;g&#226;ts). Si la poudre est conserv&#233;e dans une &lt;a class=&quot;pagelink&quot; href=&quot;Corne-&#192;-Poudre-(Objet).html&quot; title=&quot;Corne &#224; poudre&quot;&gt;corne&lt;/a&gt;, elle est prot&#233;g&#233;e contre les explosions.&lt;br /&gt;&lt;br /&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
